-- Shared BEES examples, available to every authorised organisation.
-- This migration provisions the catalogue as well as its table: deploy does not
-- depend on the unrelated general/demo seed. Future edits need a new migration.
BEGIN;
SET LOCAL lock_timeout = '10s';

CREATE TABLE "LexPlanningLibraryTemplate" (
  "id" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "pillar" TEXT NOT NULL,
  "category" TEXT,
  "department" TEXT,
  "sourceCode" TEXT NOT NULL,
  "sourceSheet" TEXT NOT NULL,
  "sourceRow" INTEGER NOT NULL,
  "ownerRole" TEXT,
  "parentObjectiveCode" TEXT,
  "parentObjectiveTitle" TEXT,
  "fields" JSONB NOT NULL,
  "notes" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
  "active" BOOLEAN NOT NULL DEFAULT true,
  "version" INTEGER NOT NULL DEFAULT 1,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "LexPlanningLibraryTemplate_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "LexPlanningLibraryTemplate_kind_check" CHECK ("kind" IN ('finding', 'objective', 'department-goal')),
  CONSTRAINT "LexPlanningLibraryTemplate_pillar_check" CHECK ("pillar" IN ('LEX', 'PEX', 'OPX', 'CMX', 'SGEX', 'FPEX')),
  CONSTRAINT "LexPlanningLibraryTemplate_category_check" CHECK ("category" IS NULL OR "category" IN ('S', 'W', 'O', 'T')),
  CONSTRAINT "LexPlanningLibraryTemplate_fields_check" CHECK (jsonb_typeof("fields") = 'object'),
  CONSTRAINT "LexPlanningLibraryTemplate_version_check" CHECK ("version" > 0),
  CONSTRAINT "LexPlanningLibraryTemplate_sourceRow_check" CHECK ("sourceRow" > 0)
);

CREATE UNIQUE INDEX "LexPlanningLibraryTemplate_kind_sourceCode_key" ON "LexPlanningLibraryTemplate"("kind", "sourceCode");
CREATE INDEX "LexPlanningLibraryTemplate_kind_active_pillar_idx" ON "LexPlanningLibraryTemplate"("kind", "active", "pillar");

