('objective:OPX-2027-OBJ02', 'objective', 'Increase customer orders delivered on time and in full from an example baseline of 80% to at least 95% by 31 March 2027.', 'OPX', NULL, NULL, 'OPX-2027-OBJ02', 'SWOT Register', '136', 'Operations Manager', NULL, NULL, '{"title":"Increase customer orders delivered on time and in full from an example baseline of 80% to at least 95% by 31 March 2027.","result":"Increase customer orders delivered on time and in full from an example baseline of 80% to at least 95% by 31 March 2027.","pillar":"OPX","alignments":["D"],"alignment":"D","measure":"Orders due in month delivered in full by originally confirmed date / all orders due","definition":"Orders due in month delivered in full by originally confirmed date / all orders due","baseline":80,"target":95,"unit":"%","direction":"HIGHER","selectionReason":"Check the causes connecting flow, changeovers and supply interruptions to late orders. The 80% baseline is an additional teaching assumption.","sourceRationale":"Check the causes connecting flow, changeovers and supply interruptions to late orders. The 80% baseline is an additional teaching assumption."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Select a responsible person and reviewed SWOT findings from your current organisation. Priority and objective weightage are not supplied in this workbook.']::text[], CURRENT_TIMESTAMP),
('objective:OPX-2027-OBJ03', 'objective', 'Increase incoming material batch acceptance from 80% in the 20-batch sample to at least 95% by 31 March 2027.', 'OPX', NULL, NULL, 'OPX-2027-OBJ03', 'SWOT Register', '137', 'Quality Manager', NULL, NULL, '{"title":"Increase incoming material batch acceptance from 80% in the 20-batch sample to at least 95% by 31 March 2027.","result":"Increase incoming material batch acceptance from 80% in the 20-batch sample to at least 95% by 31 March 2027.","pillar":"OPX","alignments":["Q"],"alignment":"Q","measure":"Batches meeting agreed specifications / all incoming batches assessed","definition":"Batches meeting agreed specifications / all incoming batches assessed","baseline":80,"target":95,"unit":"%","direction":"HIGHER","selectionReason":"Four of 20 batches failed specifications. Improve supplier conformity and consistent inspection; confirm the sample represents normal supply.","sourceRationale":"Four of 20 batches failed specifications. Improve supplier conformity and consistent inspection; confirm the sample represents normal supply."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Select a responsible person and reviewed SWOT findings from your current organisation. Priority and objective weightage are not supplied in this workbook.']::text[], CURRENT_TIMESTAMP),
('objective:MEX-2027-OBJ04', 'objective', 'Reduce the two largest customers'' share of sales from 62% to at most 45% through profitable new-customer growth by 30 June 2027, while retaining existing profitable accounts.', 'CMX', NULL, NULL, 'MEX-2027-OBJ04', 'SWOT Register', '138', 'Sales Manager', NULL, NULL, '{"title":"Reduce the two largest customers'' share of sales from 62% to at most 45% through profitable new-customer growth by 30 June 2027, while retaining existing profitable accounts.","result":"Reduce the two largest customers'' share of sales from 62% to at most 45% through profitable new-customer growth by 30 June 2027, while retaining existing profitable accounts.","pillar":"CMX","alignments":["OTHER"],"alignment":"OTHER","measure":"Revenue from the two largest customers / total company sales revenue","definition":"Revenue from the two largest customers / total company sales revenue","baseline":62,"target":45,"unit":"%","direction":"LOWER","selectionReason":"Sales concentration exposes the company to two accounts. Use the quality reputation and qualified local demand to broaden profitable sales.","sourceRationale":"Sales concentration exposes the company to two accounts. Use the quality reputation and qualified local demand to broaden profitable sales."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Select a responsible person and reviewed SWOT findings from your current organisation. Priority and objective weightage are not supplied in this workbook.', 'Describe the business focus for this objective.']::text[], CURRENT_TIMESTAMP),
('objective:FEX-2027-OBJ05', 'objective', 'Maintain available cash covering at least 3 months of essential operating expenses through 30 June 2027.', 'FPEX', NULL, NULL, 'FEX-2027-OBJ05', 'SWOT Register', '139', 'Finance Manager', NULL, NULL, '{"title":"Maintain available cash covering at least 3 months of essential operating expenses through 30 June 2027.","result":"Maintain available cash covering at least 3 months of essential operating expenses through 30 June 2027.","pillar":"FPEX","alignments":["OTHER"],"alignment":"OTHER","measure":"Available operating cash / average essential monthly cash expenses","definition":"Available operating cash / average essential monthly cash expenses","baseline":3,"target":3,"unit":"months","direction":"MAINTAIN_MIN","selectionReason":"Protect the existing 3-month cash reserve against slow collections, longer credit terms and cash tied in stock.","sourceRationale":"Protect the existing 3-month cash reserve against slow collections, longer credit terms and cash tied in stock."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Select a responsible person and reviewed SWOT findings from your current organisation. Priority and objective weightage are not supplied in this workbook.', 'Describe the business focus for this objective.']::text[], CURRENT_TIMESTAMP),
('objective:SGX-2027-OBJ06', 'objective', 'Increase named ownership of the 15 recorded business risks from 7 to all 15 by 31 March 2027 and verify the required controls.', 'SGEX', NULL, NULL, 'SGX-2027-OBJ06', 'SWOT Register', '140', 'CEO', NULL, NULL, '{"title":"Increase named ownership of the 15 recorded business risks from 7 to all 15 by 31 March 2027 and verify the required controls.","result":"Increase named ownership of the 15 recorded business risks from 7 to all 15 by 31 March 2027 and verify the required controls.","pillar":"SGEX","alignments":["OTHER"],"alignment":"OTHER","measure":"Recorded business risks with an accountable named owner; control verification checked separately","definition":"Recorded business risks with an accountable named owner; control verification checked separately","baseline":7,"target":15,"unit":"risks","direction":"HIGHER","selectionReason":"Eight risks have no owner, and a payment fraud near miss needs control follow-up. Seven owners does not prove seven effective controls.","sourceRationale":"Eight risks have no owner, and a payment fraud near miss needs control follow-up. Seven owners does not prove seven effective controls."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Select a responsible person and reviewed SWOT findings from your current organisation. Priority and objective weightage are not supplied in this workbook.', 'Describe the business focus for this objective.']::text[], CURRENT_TIMESTAMP),
('objective:PEX-2027-OBJ07', 'objective', 'Increase employees qualified for two or more key tasks from 14% to at least 40% by 30 June 2027, using practical skill assessments.', 'PEX', NULL, NULL, 'PEX-2027-OBJ07', 'SWOT Register', '141', 'HR Manager', NULL, NULL, '{"title":"Increase employees qualified for two or more key tasks from 14% to at least 40% by 30 June 2027, using practical skill assessments.","result":"Increase employees qualified for two or more key tasks from 14% to at least 40% by 30 June 2027, using practical skill assessments.","pillar":"PEX","alignments":["D"],"alignment":"D","measure":"Employees qualified for at least two key tasks / employees in the agreed skills coverage scope","definition":"Employees qualified for at least two key tasks / employees in the agreed skills coverage scope","baseline":14,"target":40,"unit":"%","direction":"HIGHER","selectionReason":"PEX-W03 records 14 qualified employees out of 100. Use experienced buddies and confirmed training needs to build practical cover. Keep the measurement scope consistent; course attendance alone does not demonstrate competence.","sourceRationale":"PEX-W03 records 14 qualified employees out of 100. Use experienced buddies and confirmed training needs to build practical cover. Keep the measurement scope consistent; course attendance alone does not demonstrate competence."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Select a responsible person and reviewed SWOT findings from your current organisation. Priority and objective weightage are not supplied in this workbook.']::text[], CURRENT_TIMESTAMP),
('objective:PEX-2027-OBJ08', 'objective', 'Increase quarterly performance reviews completed on time from 38% to at least 95% by 31 March 2027, with feedback and agreed next steps for every completed review.', 'PEX', NULL, NULL, 'PEX-2027-OBJ08', 'SWOT Register', '142', 'HR Manager', NULL, NULL, '{"title":"Increase quarterly performance reviews completed on time from 38% to at least 95% by 31 March 2027, with feedback and agreed next steps for every completed review.","result":"Increase quarterly performance reviews completed on time from 38% to at least 95% by 31 March 2027, with feedback and agreed next steps for every completed review.","pillar":"PEX","alignments":["M"],"alignment":"M","measure":"Reviews completed by their due date / scheduled quarterly reviews; feedback and next-step records checked separately","definition":"Reviews completed by their due date / scheduled quarterly reviews; feedback and next-step records checked separately","baseline":38,"target":95,"unit":"%","direction":"HIGHER","selectionReason":"PEX-W01 records 38 of 100 reviews completed on time; PEX-W02 records 31 of 50 employees receiving no feedback in three months. Timely discussions can support involvement; completion alone does not prove improved morale.","sourceRationale":"PEX-W01 records 38 of 100 reviews completed on time; PEX-W02 records 31 of 50 employees receiving no feedback in three months. Timely discussions can support involvement; completion alone does not prove improved morale."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Select a responsible person and reviewed SWOT findings from your current organisation. Priority and objective weightage are not supplied in this workbook.']::text[], CURRENT_TIMESTAMP),
('objective:OPX-2027-OBJ09', 'objective', 'Increase production lines with complete weekly waste records from 3 of 8 to all 8 by 31 March 2027, using one approved measurement method.', 'OPX', NULL, NULL, 'OPX-2027-OBJ09', 'SWOT Register', '143', 'Operations Manager', NULL, NULL, '{"title":"Increase production lines with complete weekly waste records from 3 of 8 to all 8 by 31 March 2027, using one approved measurement method.","result":"Increase production lines with complete weekly waste records from 3 of 8 to all 8 by 31 March 2027, using one approved measurement method.","pillar":"OPX","alignments":["C"],"alignment":"C","measure":"Production lines with complete weekly waste records; consistent measurement checked separately","definition":"Production lines with complete weekly waste records; consistent measurement checked separately","baseline":3,"target":8,"unit":"lines","direction":"HIGHER","selectionReason":"OPX-W03: five of eight lines lacked complete weekly waste records, leaving three with complete records. Different methods on two lines require standardisation. Establish reliable waste and cost data before setting a waste-reduction target.","sourceRationale":"OPX-W03: five of eight lines lacked complete weekly waste records, leaving three with complete records. Different methods on two lines require standardisation. Establish reliable waste and cost data before setting a waste-reduction target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Select a responsible person and reviewed SWOT findings from your current organisation. Priority and objective weightage are not supplied in this workbook.']::text[], CURRENT_TIMESTAMP),
('objective:MEX-2027-OBJ10', 'objective', 'Reduce customer complaints taking more than five working days to close from the recorded October rate of 40% to no more than 5% by 31 March 2027.', 'CMX', NULL, NULL, 'MEX-2027-OBJ10', 'SWOT Register', '144', 'Sales Manager', NULL, NULL, '{"title":"Reduce customer complaints taking more than five working days to close from the recorded October rate of 40% to no more than 5% by 31 March 2027.","result":"Reduce customer complaints taking more than five working days to close from the recorded October rate of 40% to no more than 5% by 31 March 2027.","pillar":"CMX","alignments":["Q"],"alignment":"Q","measure":"Complaints not closed within five working days / complaints received in the measured cohort","definition":"Complaints not closed within five working days / complaints received in the measured cohort","baseline":40,"target":5,"unit":"%","direction":"LOWER","selectionReason":"MEX-W03: 14 of 35 October complaints were recorded as taking over five working days to close (40%). Check whether overdue open complaints were omitted before approving the baseline. Measure each receipt cohort after the five-day deadline and include overdue open complaints.","sourceRationale":"MEX-W03: 14 of 35 October complaints were recorded as taking over five working days to close (40%). Check whether overdue open complaints were omitted before approving the baseline. Measure each receipt cohort after the five-day deadline and include overdue open complaints."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Select a responsible person and reviewed SWOT findings from your current organisation. Priority and objective weightage are not supplied in this workbook.']::text[], CURRENT_TIMESTAMP),
('department-goal:LEX-2027-OBJ01-MGT-G01', 'department-goal', 'By 31 January 2027, increase the number of reviewed department plans linked to agreed company objectives from 3 to all 6. Review each plan with its department head and record the objective number and the department''s agreed contribution.', 'LEX', NULL, 'Management', 'LEX-2027-OBJ01-MGT-G01', 'Department Goals', '9', 'CEO', 'LEX-2027-OBJ01', 'Reduce overdue open management actions from 7 at 30 September 2026 to zero by 31 March 2027.', '{"title":"By 31 January 2027, increase the number of reviewed department plans linked to agreed company objectives from 3 to all 6. Review each plan with its department head and record the objective number and the department''s agreed contribution.","measure":"Department plans linked to company objectives","definition":"Department plans linked to company objectives\nCount the six reviewed department plans that clearly identify the company objectives they support and the results the department will deliver. Target: 6 plans by 31 January 2027.","baseline":3,"target":6,"unit":"plans","direction":"HIGHER","approach":"Confirm that all six department heads and the objective owners can review the plans, agree their contributions and provide the required support before the deadline.","relevance":"LEX-W03: three of six department plans lacked a clear objective link. Link plans to execution commitments and confirm the relevance to overdue actions.","source":"LEX-W03: three of six department plans lacked a clear objective link. Link plans to execution commitments and confirm the relevance to overdue actions.\n\nAchievable check — department head to confirm: Confirm that all six department heads and the objective owners can review the plans, agree their contributions and provide the required support before the deadline."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.']::text[], CURRENT_TIMESTAMP),
('department-goal:LEX-2027-OBJ01-PRD-G01', 'department-goal', 'By 28 February 2027, reduce Production''s open overdue management actions to zero by reviewing the action list weekly and resolving each overdue item with its assigned owner.', 'LEX', NULL, 'Production', 'LEX-2027-OBJ01-PRD-G01', 'Department Goals', '10', 'Production Manager', 'LEX-2027-OBJ01', 'Reduce overdue open management actions from 7 at 30 September 2026 to zero by 31 March 2027.', '{"title":"By 28 February 2027, reduce Production''s open overdue management actions to zero by reviewing the action list weekly and resolving each overdue item with its assigned owner.","measure":"Open overdue management actions owned by Production","definition":"Open overdue management actions owned by Production\nCount Production-owned management actions whose agreed due date has passed and whose completion has not been checked and confirmed. Include any further actions that become overdue before 28 February 2027; target: zero open overdue actions at that date.","baseline":null,"target":0,"unit":"actions","direction":"LOWER","approach":"Confirm the starting number of Production actions, the work remaining, required approvals and support, and whether every overdue item can be completed and checked by the deadline.","relevance":"LEX-W02 identifies seven company-wide overdue open actions. The Production share is not given; confirm its action register before approving the goal.","source":"LEX-W02 identifies seven company-wide overdue open actions. The Production share is not given; confirm its action register before approving the goal.\n\nAchievable check — department head to confirm: Confirm the starting number of Production actions, the work remaining, required approvals and support, and whether every overdue item can be completed and checked by the deadline."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:LEX-2027-OBJ01-FIN-G01', 'department-goal', 'For complete funding requests due for a decision in January 2027, make 100% of decisions within five working days of receiving the complete request, with the result checked by 31 January 2027. Use one request log and follow up with the authorised approvers.', 'LEX', NULL, 'Finance', 'LEX-2027-OBJ01-FIN-G01', 'Department Goals', '11', 'Finance Manager', 'LEX-2027-OBJ01', 'Reduce overdue open management actions from 7 at 30 September 2026 to zero by 31 March 2027.', '{"title":"For complete funding requests due for a decision in January 2027, make 100% of decisions within five working days of receiving the complete request, with the result checked by 31 January 2027. Use one request log and follow up with the authorised approvers.","measure":"Complete funding requests decided within five working days","definition":"Complete funding requests decided within five working days\nComplete funding requests decided within five working days of receipt, divided by all complete requests whose five-working-day decision deadline falls in January 2027, multiplied by 100. Include overdue requests still awaiting a decision; record when each request became complete.","baseline":null,"target":100,"unit":"%","direction":"HIGHER","approach":"Confirm the starting response rate, complete-request rule, approver availability and whether delayed funding decisions contribute to overdue management actions.","relevance":"Additional teaching assumption: funding decisions contribute to delayed actions. Confirm this cause and measure the starting response rate.","source":"Additional teaching assumption: funding decisions contribute to delayed actions. Confirm this cause and measure the starting response rate.\n\nAchievable check — department head to confirm: Confirm the starting response rate, complete-request rule, approver availability and whether delayed funding decisions contribute to overdue management actions."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:OPX-2027-OBJ02-PRD-G01', 'department-goal', 'By 28 February 2027, reduce the main line''s average changeover time from the recorded 52 minutes to no more than 30 minutes, measured across February changeovers. Test earlier tool and material preparation and agree the work steps after checking the causes of delays.', 'OPX', NULL, 'Production', 'OPX-2027-OBJ02-PRD-G01', 'Department Goals', '12', 'Production Manager', 'OPX-2027-OBJ02', 'Increase customer orders delivered on time and in full from an example baseline of 80% to at least 95% by 31 March 2027.', '{"title":"By 28 February 2027, reduce the main line''s average changeover time from the recorded 52 minutes to no more than 30 minutes, measured across February changeovers. Test earlier tool and material preparation and agree the work steps after checking the causes of delays.","measure":"Average main-line changeover time","definition":"Average main-line changeover time\nAdd the durations of all main-line changeovers completed in February 2027 and divide by the number of changeovers. Use the same agreed timing points and include delayed changeovers; mark missing records as incomplete.","baseline":52,"target":30,"unit":"minutes","direction":"LOWER","approach":"Confirm comparable baseline timing, available people and tools, and trial results showing whether the 30-minute target is achievable.","relevance":"Existing fictional SWOT record OPX-W01: ten changeovers averaged 52 minutes in October 2026. Confirm that the same timing definition is used for later results.","source":"Existing fictional SWOT record OPX-W01: ten changeovers averaged 52 minutes in October 2026. Confirm that the same timing definition is used for later results.\n\nAchievable check — department head to confirm: Confirm comparable baseline timing, available people and tools, and trial results showing whether the 30-minute target is achievable."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.']::text[], CURRENT_TIMESTAMP),
('department-goal:OPX-2027-OBJ02-PRD-G02', 'department-goal', 'By 28 February 2027, reduce the average queue between cutting and assembly from 420 to no more than 200 pieces, using daily counts during February. Match cutting releases to assembly needs and review the queue each shift.', 'OPX', NULL, 'Production', 'OPX-2027-OBJ02-PRD-G02', 'Department Goals', '13', 'Production Manager', 'OPX-2027-OBJ02', 'Increase customer orders delivered on time and in full from an example baseline of 80% to at least 95% by 31 March 2027.', '{"title":"By 28 February 2027, reduce the average queue between cutting and assembly from 420 to no more than 200 pieces, using daily counts during February. Match cutting releases to assembly needs and review the queue each shift.","measure":"Average cutting-to-assembly work-in-progress queue","definition":"Average cutting-to-assembly work-in-progress queue\nAdd the cutting-to-assembly queue counts taken at the same agreed time on every operating day in February 2027, then divide by days counted. If any daily count is missing, mark the month incomplete rather than confirming achievement.","baseline":420,"target":200,"unit":"pieces","direction":"LOWER","approach":"Confirm the counting method, daily production needs and assembly capacity before agreeing the release limits and target.","relevance":"Existing fictional SWOT record OPX-W02: October 2026 daily counts averaged 420 pieces between cutting and assembly, against an agreed limit of 200.","source":"Existing fictional SWOT record OPX-W02: October 2026 daily counts averaged 420 pieces between cutting and assembly, against an agreed limit of 200.\n\nAchievable check — department head to confirm: Confirm the counting method, daily production needs and assembly capacity before agreeing the release limits and target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.']::text[], CURRENT_TIMESTAMP),
('department-goal:OPX-2027-OBJ02-STO-G01', 'department-goal', 'By 28 February 2027, have complete and correct material kits ready before the agreed start time for at least 98% of scheduled production changeovers in February. Prepare kits against the job requirements and check their contents before the planned start.', 'OPX', NULL, 'Stores', 'OPX-2027-OBJ02-STO-G01', 'Department Goals', '14', 'Stores Manager', 'OPX-2027-OBJ02', 'Increase customer orders delivered on time and in full from an example baseline of 80% to at least 95% by 31 March 2027.', '{"title":"By 28 February 2027, have complete and correct material kits ready before the agreed start time for at least 98% of scheduled production changeovers in February. Prepare kits against the job requirements and check their contents before the planned start.","measure":"Changeovers with material kits ready before start","definition":"Changeovers with material kits ready before start\nDivide scheduled February 2027 changeovers with a complete, correct kit ready before the agreed start time by all scheduled changeovers, then multiply by 100. Count late, incorrect or incomplete kits as failures.","baseline":null,"target":98,"unit":"%","direction":"HIGHER","approach":"Measure the starting readiness rate and confirm supplier availability, storage space and staff time before approving the 98% target.","relevance":"Illustrative assumption: material readiness contributes to changeover delays. Confirm the cause and measure the starting readiness rate before approving this goal.","source":"Illustrative assumption: material readiness contributes to changeover delays. Confirm the cause and measure the starting readiness rate before approving this goal.\n\nAchievable check — department head to confirm: Measure the starting readiness rate and confirm supplier availability, storage space and staff time before approving the 98% target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:OPX-2027-OBJ02-PLN-G01', 'department-goal', 'By 28 February 2027, achieve on-time completion for at least 95% of production jobs due in February. Confirm material availability and production capacity before agreeing completion dates, then review jobs that may finish late each day.', 'OPX', NULL, 'Planning', 'OPX-2027-OBJ02-PLN-G01', 'Department Goals', '15', 'Planning Manager', 'OPX-2027-OBJ02', 'Increase customer orders delivered on time and in full from an example baseline of 80% to at least 95% by 31 March 2027.', '{"title":"By 28 February 2027, achieve on-time completion for at least 95% of production jobs due in February. Confirm material availability and production capacity before agreeing completion dates, then review jobs that may finish late each day.","measure":"Jobs completed by the agreed production date","definition":"Jobs completed by the agreed production date\nDivide jobs due in February 2027 that finished by their originally agreed production dates by all jobs due that month, then multiply by 100. Include unfinished overdue jobs and keep original dates for scoring.","baseline":null,"target":95,"unit":"%","direction":"HIGHER","approach":"Measure the starting completion rate and confirm capacity, material supply and department commitments needed to achieve 95%.","relevance":"Illustrative assumption: schedule adherence is a relevant delivery driver. Measure jobs due and completed by their agreed dates; do not improve the rate by moving dates after the event.","source":"Illustrative assumption: schedule adherence is a relevant delivery driver. Measure jobs due and completed by their agreed dates; do not improve the rate by moving dates after the event.\n\nAchievable check — department head to confirm: Measure the starting completion rate and confirm capacity, material supply and department commitments needed to achieve 95%."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:OPX-2027-OBJ03-PUR-G01', 'department-goal', 'By 31 March 2027, increase incoming material batch acceptance from the recorded 80% sample rate to at least 95% of batches received in March. Confirm material requirements with suppliers and follow up batches that fail the agreed checks.', 'OPX', NULL, 'Purchasing', 'OPX-2027-OBJ03-PUR-G01', 'Department Goals', '16', 'Purchasing Manager', 'OPX-2027-OBJ03', 'Increase incoming material batch acceptance from 80% in the 20-batch sample to at least 95% by 31 March 2027.', '{"title":"By 31 March 2027, increase incoming material batch acceptance from the recorded 80% sample rate to at least 95% of batches received in March. Confirm material requirements with suppliers and follow up batches that fail the agreed checks.","measure":"Supplied batches meeting agreed specifications","definition":"Supplied batches meeting agreed specifications\nDivide March 2027 incoming batches confirmed to meet all agreed specifications by all incoming batches received that month, then multiply by 100. Failed batches and batches without completed required checks do not count as accepted.","baseline":80,"target":95,"unit":"%","direction":"HIGHER","approach":"Confirm a comparable baseline, supplier improvement commitments and inspection capacity before approving the 95% target.","relevance":"Calculated from fictional SWOT record OPX-T03: 16 of 20 inspected batches met specification in October 2026. Verify a representative baseline for ongoing reporting.","source":"Calculated from fictional SWOT record OPX-T03: 16 of 20 inspected batches met specification in October 2026. Verify a representative baseline for ongoing reporting.\n\nAchievable check — department head to confirm: Confirm a comparable baseline, supplier improvement commitments and inspection capacity before approving the 95% target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.']::text[], CURRENT_TIMESTAMP),
('department-goal:OPX-2027-OBJ03-QUA-G01', 'department-goal', 'By 31 January 2027, complete and record every required incoming-material check before release for 100% of receipts released to production in January. Use a release checklist and hold materials whenever required checks or records are missing.', 'OPX', NULL, 'Quality', 'OPX-2027-OBJ03-QUA-G01', 'Department Goals', '17', 'Quality Manager', 'OPX-2027-OBJ03', 'Increase incoming material batch acceptance from 80% in the 20-batch sample to at least 95% by 31 March 2027.', '{"title":"By 31 January 2027, complete and record every required incoming-material check before release for 100% of receipts released to production in January. Use a release checklist and hold materials whenever required checks or records are missing.","measure":"Receipts fully checked before material release","definition":"Receipts fully checked before material release\nDivide January 2027 receipts released to production with all required checks completed and recorded beforehand by all receipts released that month, then multiply by 100. Missing, late or incomplete check records fail this measure.","baseline":null,"target":100,"unit":"%","direction":"HIGHER","approach":"Establish the baseline and confirm inspection staff, equipment, record access and authority to hold materials before approving the target.","relevance":"Baseline requires measurement. Fictional record OPX-W05 reports four missing records and three incomplete records among 20 receipts; it does not establish how many checks occurred before release.","source":"Baseline requires measurement. Fictional record OPX-W05 reports four missing records and three incomplete records among 20 receipts; it does not establish how many checks occurred before release.\n\nAchievable check — department head to confirm: Establish the baseline and confirm inspection staff, equipment, record access and authority to hold materials before approving the target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:OPX-2027-OBJ03-PRD-G01', 'department-goal', 'By 31 January 2027, ensure 100% of production jobs started in January use materials with recorded quality release approval before the job starts. Check approval against the job''s materials before use and stop the start when approval is missing.', 'OPX', NULL, 'Production', 'OPX-2027-OBJ03-PRD-G01', 'Department Goals', '18', 'Production Manager', 'OPX-2027-OBJ03', 'Increase incoming material batch acceptance from 80% in the 20-batch sample to at least 95% by 31 March 2027.', '{"title":"By 31 January 2027, ensure 100% of production jobs started in January use materials with recorded quality release approval before the job starts. Check approval against the job''s materials before use and stop the start when approval is missing.","measure":"Jobs started with material release approval recorded","definition":"Jobs started with material release approval recorded\nDivide January 2027 production jobs whose starting materials all had recorded approval before job start by all jobs started that month, then multiply by 100. Any missing or late approval makes the job a failure.","baseline":null,"target":100,"unit":"%","direction":"HIGHER","approach":"Measure the baseline and confirm that operators can identify materials, access approvals and obtain timely support from Quality.","relevance":"Illustrative assumption: verification at the point of use is needed to prevent unapproved material entering production. Measure current compliance before approving the contribution.","source":"Illustrative assumption: verification at the point of use is needed to prevent unapproved material entering production. Measure current compliance before approving the contribution.\n\nAchievable check — department head to confirm: Measure the baseline and confirm that operators can identify materials, access approvals and obtain timely support from Quality."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:MEX-2027-OBJ04-SAL-G01', 'department-goal', 'By 30 June 2027, achieve June sales from new customers equal to 40% of the company’s October 2026 sales. Follow up agreed potential customers and turn suitable enquiries into profitable orders while retaining existing profitable customers.', 'CMX', NULL, 'Sales', 'MEX-2027-OBJ04-SAL-G01', 'Department Goals', '19', 'Sales Manager', 'MEX-2027-OBJ04', 'Reduce the two largest customers'' share of sales from 62% to at most 45% through profitable new-customer growth by 30 June 2027, while retaining existing profitable accounts.', '{"title":"By 30 June 2027, achieve June sales from new customers equal to 40% of the company’s October 2026 sales. Follow up agreed potential customers and turn suitable enquiries into profitable orders while retaining existing profitable customers.","measure":"New-customer monthly revenue / October 2026 sales","definition":"New-customer monthly revenue / October 2026 sales\nDivide June 2027 sales from customers who meet the agreed new-customer definition by total October 2026 company sales, then multiply by 100. Finance must use the same sales-value basis for both periods.","baseline":null,"target":40,"unit":"%","direction":"HIGHER","approach":"Confirm the starting sales figures, likely orders, profit and delivery capacity before approving the target.","relevance":"Illustrative assumption: profitable new-customer revenue expands the sales base while existing profitable accounts are retained. Confirm October sales, current new-customer revenue and the revenue needed to reach the company concentration target.","source":"Illustrative assumption: profitable new-customer revenue expands the sales base while existing profitable accounts are retained. Confirm October sales, current new-customer revenue and the revenue needed to reach the company concentration target.\n\nAchievable check — department head to confirm: Confirm the starting sales figures, likely orders, profit and delivery capacity before approving the target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:MEX-2027-OBJ04-MKT-G01', 'department-goal', 'By 31 March 2027, provide 20 different potential new customers that Sales accepts as suitable for follow-up. Use the agreed customer checks, record each potential customer and agree the next contact with Sales so the same potential customer is counted only once.', 'CMX', NULL, 'Marketing', 'MEX-2027-OBJ04-MKT-G01', 'Department Goals', '20', 'Marketing Manager', 'MEX-2027-OBJ04', 'Reduce the two largest customers'' share of sales from 62% to at most 45% through profitable new-customer growth by 30 June 2027, while retaining existing profitable accounts.', '{"title":"By 31 March 2027, provide 20 different potential new customers that Sales accepts as suitable for follow-up. Use the agreed customer checks, record each potential customer and agree the next contact with Sales so the same potential customer is counted only once.","measure":"Qualified new-customer prospects accepted by Sales","definition":"Qualified new-customer prospects accepted by Sales\nCount different prospects submitted by Marketing and accepted by Sales between plan approval and 31 March 2027. Keep the acceptance date and the agreed checks for each prospect.","baseline":null,"target":20,"unit":"prospects","direction":"HIGHER","approach":"Confirm the agreed customer checks, available marketing time and expected number of suitable enquiries before approving the target.","relevance":"Illustrative assumption: 20 qualified prospects can support the planned sales growth. Agree qualification criteria and measure the current pipeline; enquiries alone are not confirmed customers.","source":"Illustrative assumption: 20 qualified prospects can support the planned sales growth. Agree qualification criteria and measure the current pipeline; enquiries alone are not confirmed customers.\n\nAchievable check — department head to confirm: Confirm the agreed customer checks, available marketing time and expected number of suitable enquiries before approving the target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:MEX-2027-OBJ04-OPS-G01', 'department-goal', 'By 31 May 2027, achieve first-time customer acceptance for at least 95% of new-customer trial orders due for acceptance in May. Confirm customer requirements and check the work before delivery so trial orders can pass without rework.', 'CMX', NULL, 'Operations', 'MEX-2027-OBJ04-OPS-G01', 'Department Goals', '21', 'Operations Manager', 'MEX-2027-OBJ04', 'Reduce the two largest customers'' share of sales from 62% to at most 45% through profitable new-customer growth by 30 June 2027, while retaining existing profitable accounts.', '{"title":"By 31 May 2027, achieve first-time customer acceptance for at least 95% of new-customer trial orders due for acceptance in May. Confirm customer requirements and check the work before delivery so trial orders can pass without rework.","measure":"New-customer trial orders accepted first time","definition":"New-customer trial orders accepted first time\nDivide trial orders accepted at the first customer check by all new-customer trial orders due for acceptance in May 2027, then multiply by 100. Include rejected orders and overdue orders awaiting confirmation.","baseline":null,"target":95,"unit":"%","direction":"HIGHER","approach":"Confirm the starting acceptance rate, expected trial orders, customer checks and available production time before approving the target.","relevance":"Illustrative assumption: successful trial orders support conversion to recurring accounts. Confirm acceptance criteria with Sales and measure the starting acceptance rate.","source":"Illustrative assumption: successful trial orders support conversion to recurring accounts. Confirm acceptance criteria with Sales and measure the starting acceptance rate.\n\nAchievable check — department head to confirm: Confirm the starting acceptance rate, expected trial orders, customer checks and available production time before approving the target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:FEX-2027-OBJ05-FIN-G01', 'department-goal', 'Meet 100% of the agreed weekly deadlines through 30 June 2027 for a complete, updated 13-week cash forecast. Check expected customer receipts and planned payments with the relevant departments each week before sharing the forecast with management.', 'FPEX', NULL, 'Finance', 'FEX-2027-OBJ05-FIN-G01', 'Department Goals', '22', 'Finance Manager', 'FEX-2027-OBJ05', 'Maintain available cash covering at least 3 months of essential operating expenses through 30 June 2027.', '{"title":"Meet 100% of the agreed weekly deadlines through 30 June 2027 for a complete, updated 13-week cash forecast. Check expected customer receipts and planned payments with the relevant departments each week before sharing the forecast with management.","measure":"Weekly cut-offs with an updated cash forecast","definition":"Weekly cut-offs with an updated cash forecast\nDivide weekly deadlines met with a complete forecast by all scheduled weekly deadlines from the approved start date through 30 June 2027, then multiply by 100. Each forecast must cover the following 13 weeks.","baseline":null,"target":100,"unit":"%","direction":"HIGHER","approach":"Confirm who supplies the figures, when they are available and the time Finance needs to update and check them.","relevance":"FEX-W03: the October 2026 forecast was six weeks old. Historical weekly completion percentage is not available; measure it before confirming a numerical baseline.","source":"FEX-W03: the October 2026 forecast was six weeks old. Historical weekly completion percentage is not available; measure it before confirming a numerical baseline.\n\nAchievable check — department head to confirm: Confirm who supplies the figures, when they are available and the time Finance needs to update and check them."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:FEX-2027-OBJ05-SAL-G01', 'department-goal', 'By 31 March 2027, increase invoices paid by their agreed due dates from 88% to at least 95%, measured for invoices due in March. Send reminders before payment is due and follow up unpaid invoices with customers and Finance.', 'FPEX', NULL, 'Sales', 'FEX-2027-OBJ05-SAL-G01', 'Department Goals', '23', 'Sales Manager', 'FEX-2027-OBJ05', 'Maintain available cash covering at least 3 months of essential operating expenses through 30 June 2027.', '{"title":"By 31 March 2027, increase invoices paid by their agreed due dates from 88% to at least 95%, measured for invoices due in March. Send reminders before payment is due and follow up unpaid invoices with customers and Finance.","measure":"Invoices paid by due date / invoices due in month","definition":"Invoices paid by due date / invoices due in month\nDivide March 2027 invoices paid in full by their originally agreed due dates by all invoices due in March, then multiply by 100. Use invoice counts, not invoice values.","baseline":88,"target":95,"unit":"%","direction":"HIGHER","approach":"Confirm customer payment terms, disputed invoices and the follow-up support needed before approving the target.","relevance":"FEX-S05: 88 of 100 invoices due in October 2026 were paid by their agreed due dates. This is a teaching example from the SWOT register.","source":"FEX-S05: 88 of 100 invoices due in October 2026 were paid by their agreed due dates. This is a teaching example from the SWOT register.\n\nAchievable check — department head to confirm: Confirm customer payment terms, disputed invoices and the follow-up support needed before approving the target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.']::text[], CURRENT_TIMESTAMP),
('department-goal:FEX-2027-OBJ05-STO-G01', 'department-goal', 'By 31 March 2027, reduce the value of stock idle for more than 180 days from KES 6 million to no more than KES 4.2 million through use or sale. Review old stock monthly with Production, Sales and Finance and agree specific uses or buyers.', 'FPEX', NULL, 'Stores', 'FEX-2027-OBJ05-STO-G01', 'Department Goals', '24', 'Stores Manager', 'FEX-2027-OBJ05', 'Maintain available cash covering at least 3 months of essential operating expenses through 30 June 2027.', '{"title":"By 31 March 2027, reduce the value of stock idle for more than 180 days from KES 6 million to no more than KES 4.2 million through use or sale. Review old stock monthly with Production, Sales and Finance and agree specific uses or buyers.","measure":"Aged stock value, excluding write-off-only reductions","definition":"Aged stock value, excluding write-off-only reductions\nCheck all stock idle for more than 180 days at 31 March 2027 using the same rules for valuing stock as the starting figure. Add back reductions recorded only by writing stock value down or changing its category, and keep records of real use or sale.","baseline":6000000,"target":4200000,"unit":"KES","direction":"LOWER","approach":"Confirm stock condition, possible uses, buyers and sale approvals; stock reduction alone does not prove cash has been received.","relevance":"FEX-W02: October 2026 inventory ageing shows KES 6 million of stock with no movement for more than 180 days. This is a teaching example from the SWOT register. For the goal, add back reductions caused only by write-offs or reclassification. Finance checks actual cash received separately.","source":"FEX-W02: October 2026 inventory ageing shows KES 6 million of stock with no movement for more than 180 days. This is a teaching example from the SWOT register. For the goal, add back reductions caused only by write-offs or reclassification. Finance checks actual cash received separately.\n\nAchievable check — department head to confirm: Confirm stock condition, possible uses, buyers and sale approvals; stock reduction alone does not prove cash has been received."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.']::text[], CURRENT_TIMESTAMP),
('department-goal:SGX-2027-OBJ06-FIN-G01', 'department-goal', 'By 31 March 2027, have a second person check 100% of supplier bank account changes before they are applied. Confirm each request through an existing trusted supplier contact, record the check and continue checking every later change.', 'SGEX', NULL, 'Finance', 'SGX-2027-OBJ06-FIN-G01', 'Department Goals', '25', 'Finance Manager', 'SGX-2027-OBJ06', 'Increase named ownership of the 15 recorded business risks from 7 to all 15 by 31 March 2027 and verify the required controls.', '{"title":"By 31 March 2027, have a second person check 100% of supplier bank account changes before they are applied. Confirm each request through an existing trusted supplier contact, record the check and continue checking every later change.","measure":"Bank-detail changes independently checked before update","definition":"Bank-detail changes independently checked before update\nDivide supplier bank account changes checked by a second person before the update by all changes applied in March 2027, then multiply by 100. Continue the monthly check after March and keep the dated evidence.","baseline":null,"target":100,"unit":"%","direction":"HIGHER","approach":"Confirm the checker, trusted contact records and approval process before approving the target and method.","relevance":"SGX-T03 records four suspected requests and one near miss in October 2026, but does not establish the verification percentage for all bank-detail changes. Confirm the baseline from change records.","source":"SGX-T03 records four suspected requests and one near miss in October 2026, but does not establish the verification percentage for all bank-detail changes. Confirm the baseline from change records.\n\nAchievable check — department head to confirm: Confirm the checker, trusted contact records and approval process before approving the target and method."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:SGX-2027-OBJ06-OPS-G01', 'department-goal', 'By 28 February 2027, confirm that 100% of the agreed steps for preventing or reducing risks assigned to Operations are working. Test each step, record the result and correct any failure before the final check.', 'SGEX', NULL, 'Operations', 'SGX-2027-OBJ06-OPS-G01', 'Department Goals', '26', 'Operations Manager', 'SGX-2027-OBJ06', 'Increase named ownership of the 15 recorded business risks from 7 to all 15 by 31 March 2027 and verify the required controls.', '{"title":"By 28 February 2027, confirm that 100% of the agreed steps for preventing or reducing risks assigned to Operations are working. Test each step, record the result and correct any failure before the final check.","measure":"Required operational risk controls verified effective","definition":"Required operational risk controls verified effective\nDivide required Operations risk controls with evidence of a passed check by all controls on the agreed list, then multiply by 100. Untested or failed controls remain incomplete at the deadline.","baseline":null,"target":100,"unit":"%","direction":"HIGHER","approach":"Confirm the full control list, test method, responsible people and resources needed to correct failures.","relevance":"SGX-W01 establishes company risk-owner coverage of 7 of 15. It does not establish Operations control effectiveness or its control count; confirm both from the assigned risks.","source":"SGX-W01 establishes company risk-owner coverage of 7 of 15. It does not establish Operations control effectiveness or its control count; confirm both from the assigned risks.\n\nAchievable check — department head to confirm: Confirm the full control list, test method, responsible people and resources needed to correct failures."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:SGX-2027-OBJ06-HR-G01', 'department-goal', 'From 10 November 2026, ensure every contractor, or 100%, completes the site safety briefing before starting work. Check the completion record before work is allowed and continue this check for every contractor who starts work after that date.', 'SGEX', NULL, 'HR', 'SGX-2027-OBJ06-HR-G01', 'Department Goals', '27', 'HR Manager', 'SGX-2027-OBJ06', 'Increase named ownership of the 15 recorded business risks from 7 to all 15 by 31 March 2027 and verify the required controls.', '{"title":"From 10 November 2026, ensure every contractor, or 100%, completes the site safety briefing before starting work. Check the completion record before work is allowed and continue this check for every contractor who starts work after that date.","measure":"Contractors inducted before work / contractors starting","definition":"Contractors inducted before work / contractors starting\nFor contractors starting work from 10 November 2026, divide those with a completed briefing before their first work time by all contractors starting, then multiply by 100. Check each arrival and review the totals monthly.","baseline":60,"target":100,"unit":"%","direction":"HIGHER","approach":"Arrange immediate briefing for any current contractor without completion evidence and confirm who checks each contractor before work starts.","relevance":"SGX-W02: 9 of 15 sampled contractors completed induction before work in October 2026, equivalent to 60%. The sample does not establish the full-site population rate. Start the corrective action immediately; do not wait for objective approval.","source":"SGX-W02: 9 of 15 sampled contractors completed induction before work in October 2026, equivalent to 60%. The sample does not establish the full-site population rate. Start the corrective action immediately; do not wait for objective approval.\n\nAchievable check — department head to confirm: Arrange immediate briefing for any current contractor without completion evidence and confirm who checks each contractor before work starts."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.']::text[], CURRENT_TIMESTAMP),
('department-goal:SGX-2027-OBJ06-MGT-G01', 'department-goal', 'By 31 January 2027, increase recorded business risks with a named responsible person from 7 to all 15. Discuss each risk with the proposed person, agree the responsibility and record the appointment so every risk has one clear owner.', 'SGEX', NULL, 'Management', 'SGX-2027-OBJ06-MGT-G01', 'Department Goals', '28', 'CEO', 'SGX-2027-OBJ06', 'Increase named ownership of the 15 recorded business risks from 7 to all 15 by 31 March 2027 and verify the required controls.', '{"title":"By 31 January 2027, increase recorded business risks with a named responsible person from 7 to all 15. Discuss each risk with the proposed person, agree the responsibility and record the appointment so every risk has one clear owner.","measure":"Recorded business risks with a named owner","definition":"Recorded business risks with a named owner\nCount the 15 recorded risks that have one named owner who has accepted the responsibility by 31 January 2027. Whether the required controls work is checked separately.","baseline":7,"target":15,"unit":"risks","direction":"HIGHER","approach":"Confirm that each proposed owner has the authority, knowledge and time needed to manage the assigned risk.","relevance":"SGX-W01: eight of 15 recorded risks have no owner, leaving seven with owners. Ownership is separate from evidence that controls work.","source":"SGX-W01: eight of 15 recorded risks have no owner, leaving seven with owners. Ownership is separate from evidence that controls work.\n\nAchievable check — department head to confirm: Confirm that each proposed owner has the authority, knowledge and time needed to manage the assigned risk."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.']::text[], CURRENT_TIMESTAMP),
('department-goal:PEX-2027-OBJ07-HR-G01', 'department-goal', 'By 31 January 2027, increase confirmed training needs lists from 2 to all 6 reviewed departments by checking current skills and agreeing training priorities with each department head.', 'PEX', NULL, 'HR', 'PEX-2027-OBJ07-HR-G01', 'Department Goals', '29', 'HR Manager', 'PEX-2027-OBJ07', 'Increase employees qualified for two or more key tasks from 14% to at least 40% by 30 June 2027, using practical skill assessments.', '{"title":"By 31 January 2027, increase confirmed training needs lists from 2 to all 6 reviewed departments by checking current skills and agreeing training priorities with each department head.","measure":"Departments with a confirmed training needs list","definition":"Departments with a confirmed training needs list\nCount the six reviewed departments that have a confirmed list of skill gaps and training priorities. Target: 6 departments by 31 January 2027.","baseline":2,"target":6,"unit":"departments","direction":"HIGHER","approach":"Confirm access to current skills records, the people who will check skills and enough time with all six department heads to agree the lists.","relevance":"PEX-W05: four of six departments have no confirmed training needs list, leaving two with a list. Confirm priorities with each department against the skills matrix. Target is illustrative.","source":"PEX-W05: four of six departments have no confirmed training needs list, leaving two with a list. Confirm priorities with each department against the skills matrix. Target is illustrative.\n\nAchievable check — department head to confirm: Confirm access to current skills records, the people who will check skills and enough time with all six department heads to agree the lists."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.']::text[], CURRENT_TIMESTAMP),
('department-goal:PEX-2027-OBJ07-PRD-G01', 'department-goal', 'By 30 June 2027, qualify at least 40% of Production employees covered by the agreed skills plan for two or more key production tasks, using practical training followed by observed skill checks.', 'PEX', NULL, 'Production', 'PEX-2027-OBJ07-PRD-G01', 'Department Goals', '30', 'Production Manager', 'PEX-2027-OBJ07', 'Increase employees qualified for two or more key tasks from 14% to at least 40% by 30 June 2027, using practical skill assessments.', '{"title":"By 30 June 2027, qualify at least 40% of Production employees covered by the agreed skills plan for two or more key production tasks, using practical training followed by observed skill checks.","measure":"Production employees qualified for at least two key tasks / Production employees in scope","definition":"Production employees qualified for at least two key tasks / Production employees in scope\nProduction employees with recorded qualification for at least two agreed key tasks, divided by all Production employees covered by the agreed skills plan, multiplied by 100, measured on 30 June 2027. Count confirmed practical ability, not training attendance.","baseline":null,"target":40,"unit":"%","direction":"HIGHER","approach":"Confirm the employee and task lists, the current qualified count, trainers, equipment access and enough work time for practice and skill checks before approving the 40% target.","relevance":"PEX-W03 gives a company-wide baseline of 14 out of 100, not a Production baseline. Confirm the department scope and starting count. Require observed practical assessment before qualification. Target is illustrative.","source":"PEX-W03 gives a company-wide baseline of 14 out of 100, not a Production baseline. Confirm the department scope and starting count. Require observed practical assessment before qualification. Target is illustrative.\n\nAchievable check — department head to confirm: Confirm the employee and task lists, the current qualified count, trainers, equipment access and enough work time for practice and skill checks before approving the 40% target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:PEX-2027-OBJ07-STO-G01', 'department-goal', 'By 30 June 2027, qualify at least 40% of Stores employees covered by the agreed skills plan for two or more key stores tasks, using practical training followed by observed skill checks.', 'PEX', NULL, 'Stores', 'PEX-2027-OBJ07-STO-G01', 'Department Goals', '31', 'Stores Manager', 'PEX-2027-OBJ07', 'Increase employees qualified for two or more key tasks from 14% to at least 40% by 30 June 2027, using practical skill assessments.', '{"title":"By 30 June 2027, qualify at least 40% of Stores employees covered by the agreed skills plan for two or more key stores tasks, using practical training followed by observed skill checks.","measure":"Stores employees qualified for at least two key tasks / Stores employees in scope","definition":"Stores employees qualified for at least two key tasks / Stores employees in scope\nStores employees with recorded qualification for at least two agreed key tasks, divided by all Stores employees covered by the agreed skills plan, multiplied by 100, measured on 30 June 2027. Count confirmed practical ability, not training attendance.","baseline":null,"target":40,"unit":"%","direction":"HIGHER","approach":"Confirm the employee and task lists, the current qualified count, suitable trainers and enough time to practise and check each task before approving the 40% target.","relevance":"PEX-W03 gives no Stores-specific baseline. Check receiving, storage, picking and issuing skills as relevant. Count assessed competence, not attendance. These department examples do not alone establish the company result. Target is illustrative.","source":"PEX-W03 gives no Stores-specific baseline. Check receiving, storage, picking and issuing skills as relevant. Count assessed competence, not attendance. These department examples do not alone establish the company result. Target is illustrative.\n\nAchievable check — department head to confirm: Confirm the employee and task lists, the current qualified count, suitable trainers and enough time to practise and check each task before approving the 40% target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:PEX-2027-OBJ08-HR-G01', 'department-goal', 'For the quarter ending 31 March 2027, ensure 100% of completed performance reviews contain employee confirmation that feedback was shared and a record of agreed next steps. HR will check each completed review record and follow up missing details.', 'PEX', NULL, 'HR', 'PEX-2027-OBJ08-HR-G01', 'Department Goals', '32', 'HR Manager', 'PEX-2027-OBJ08', 'Increase quarterly performance reviews completed on time from 38% to at least 95% by 31 March 2027, with feedback and agreed next steps for every completed review.', '{"title":"For the quarter ending 31 March 2027, ensure 100% of completed performance reviews contain employee confirmation that feedback was shared and a record of agreed next steps. HR will check each completed review record and follow up missing details.","measure":"Completed reviews with feedback acknowledged and next steps recorded / completed reviews","definition":"Completed reviews with feedback acknowledged and next steps recorded / completed reviews\nCompleted quarterly reviews with employee confirmation of feedback and recorded agreed next steps, divided by all completed quarterly reviews for the quarter ending 31 March 2027, multiplied by 100. This measures review-record completeness; timely review completion is measured separately.","baseline":null,"target":100,"unit":"%","direction":"HIGHER","approach":"Confirm the starting completeness rate, an agreed review form, how employees confirm receipt of feedback and enough HR time to check and follow up the records.","relevance":"PEX-W02 records 31 of 50 employees reporting no feedback. It does not measure review-record completeness; establish that baseline separately and check employee acknowledgement. Target is illustrative.","source":"PEX-W02 records 31 of 50 employees reporting no feedback. It does not measure review-record completeness; establish that baseline separately and check employee acknowledgement. Target is illustrative.\n\nAchievable check — department head to confirm: Confirm the starting completeness rate, an agreed review form, how employees confirm receipt of feedback and enough HR time to check and follow up the records."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:PEX-2027-OBJ08-PRD-G01', 'department-goal', 'For the quarter ending 31 March 2027, complete at least 95% of scheduled Production performance reviews by their agreed due dates, using a review schedule and weekly follow-up with the responsible managers.', 'PEX', NULL, 'Production', 'PEX-2027-OBJ08-PRD-G01', 'Department Goals', '33', 'Production Manager', 'PEX-2027-OBJ08', 'Increase quarterly performance reviews completed on time from 38% to at least 95% by 31 March 2027, with feedback and agreed next steps for every completed review.', '{"title":"For the quarter ending 31 March 2027, complete at least 95% of scheduled Production performance reviews by their agreed due dates, using a review schedule and weekly follow-up with the responsible managers.","measure":"Production reviews completed on time / scheduled Production quarterly reviews","definition":"Production reviews completed on time / scheduled Production quarterly reviews\nProduction quarterly reviews completed on or before their agreed due dates, divided by all Production quarterly reviews due during January to March 2027, multiplied by 100. Reviews that are late or still incomplete at 31 March do not count as completed on time.","baseline":null,"target":95,"unit":"%","direction":"HIGHER","approach":"Confirm the department''s starting rate, the number of reviews due, manager and employee availability, and access to the information needed for useful review discussions.","relevance":"PEX-W01 provides a company-wide 38% rate, not a Production rate. Establish the department baseline and scheduled review population. Check meaningful feedback alongside completion. Target is illustrative.","source":"PEX-W01 provides a company-wide 38% rate, not a Production rate. Establish the department baseline and scheduled review population. Check meaningful feedback alongside completion. Target is illustrative.\n\nAchievable check — department head to confirm: Confirm the department''s starting rate, the number of reviews due, manager and employee availability, and access to the information needed for useful review discussions."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:PEX-2027-OBJ08-FIN-G01', 'department-goal', 'For the quarter ending 31 March 2027, complete at least 95% of scheduled Finance performance reviews by their agreed due dates, using a review schedule and weekly follow-up with the responsible managers.', 'PEX', NULL, 'Finance', 'PEX-2027-OBJ08-FIN-G01', 'Department Goals', '34', 'Finance Manager', 'PEX-2027-OBJ08', 'Increase quarterly performance reviews completed on time from 38% to at least 95% by 31 March 2027, with feedback and agreed next steps for every completed review.', '{"title":"For the quarter ending 31 March 2027, complete at least 95% of scheduled Finance performance reviews by their agreed due dates, using a review schedule and weekly follow-up with the responsible managers.","measure":"Finance reviews completed on time / scheduled Finance quarterly reviews","definition":"Finance reviews completed on time / scheduled Finance quarterly reviews\nFinance quarterly reviews completed on or before their agreed due dates, divided by all Finance quarterly reviews due during January to March 2027, multiplied by 100. Reviews that are late or still incomplete at 31 March do not count as completed on time.","baseline":null,"target":95,"unit":"%","direction":"HIGHER","approach":"Confirm the department''s starting rate, the number of reviews due, manager and employee availability, and access to the information needed for useful review discussions.","relevance":"PEX-W01 provides a company-wide 38% rate, not a Finance rate. Establish the department baseline and scheduled review population. Company performance uses the total review counts across all departments, not an average of department percentages. Target is illustrative.","source":"PEX-W01 provides a company-wide 38% rate, not a Finance rate. Establish the department baseline and scheduled review population. Company performance uses the total review counts across all departments, not an average of department percentages. Target is illustrative.\n\nAchievable check — department head to confirm: Confirm the department''s starting rate, the number of reviews due, manager and employee availability, and access to the information needed for useful review discussions."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:OPX-2027-OBJ09-PRD-G01', 'department-goal', 'By 28 February 2027, increase lines with complete weekly waste records from 3 of 8 to all 8, for every full reporting week in February. Assign a recorder for each line and check all required shift entries before the weekly review.', 'OPX', NULL, 'Production', 'OPX-2027-OBJ09-PRD-G01', 'Department Goals', '35', 'Production Manager', 'OPX-2027-OBJ09', 'Increase production lines with complete weekly waste records from 3 of 8 to all 8 by 31 March 2027, using one approved measurement method.', '{"title":"By 28 February 2027, increase lines with complete weekly waste records from 3 of 8 to all 8, for every full reporting week in February. Assign a recorder for each line and check all required shift entries before the weekly review.","measure":"Production lines with complete weekly waste records","definition":"Production lines with complete weekly waste records\nFor each full reporting week in February 2027, count lines with every required shift, waste quantity, unit and category recorded. The target is eight lines each week; missing entries prevent a line from counting.","baseline":3,"target":8,"unit":"lines","direction":"HIGHER","approach":"Confirm recording time, clear waste categories and suitable measuring equipment on all eight lines before approving the target.","relevance":"OPX-W03: five of eight lines had no complete weekly waste record, leaving three complete. Count a line only when all required shifts, quantities and waste categories are recorded. Target is illustrative.","source":"OPX-W03: five of eight lines had no complete weekly waste record, leaving three complete. Count a line only when all required shifts, quantities and waste categories are recorded. Target is illustrative.\n\nAchievable check — department head to confirm: Confirm recording time, clear waste categories and suitable measuring equipment on all eight lines before approving the target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.']::text[], CURRENT_TIMESTAMP),
('department-goal:OPX-2027-OBJ09-QUA-G01', 'department-goal', 'By 28 February 2027, verify that all eight production lines use the approved waste measurement method during normal work. Check the units, waste definitions and measuring equipment on each line, and correct any gaps before completing the verification.', 'OPX', NULL, 'Quality', 'OPX-2027-OBJ09-QUA-G01', 'Department Goals', '36', 'Quality Manager', 'OPX-2027-OBJ09', 'Increase production lines with complete weekly waste records from 3 of 8 to all 8 by 31 March 2027, using one approved measurement method.', '{"title":"By 28 February 2027, verify that all eight production lines use the approved waste measurement method during normal work. Check the units, waste definitions and measuring equipment on each line, and correct any gaps before completing the verification.","measure":"Lines verified to use the approved waste measurement method","definition":"Lines verified to use the approved waste measurement method\nCount lines that pass a recorded workplace check against the approved method by 28 February 2027. All eight must pass; a line with an unresolved gap does not count.","baseline":null,"target":8,"unit":"lines","direction":"HIGHER","approach":"Measure the current position and confirm one approved method, suitable equipment and time to check and correct all eight lines.","relevance":"OPX-W03: two lines used different methods; the number meeting one agreed method is unknown. Agree units, waste definitions and checking method, then assess all eight lines. Target is illustrative.","source":"OPX-W03: two lines used different methods; the number meeting one agreed method is unknown. Agree units, waste definitions and checking method, then assess all eight lines. Target is illustrative.\n\nAchievable check — department head to confirm: Measure the current position and confirm one approved method, suitable equipment and time to check and correct all eight lines."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:OPX-2027-OBJ09-FIN-G01', 'department-goal', 'By 31 March 2027, record checked material costs for 100% of complete weekly waste records for weeks ending in March across the eight production lines. Confirm quantities with Production and apply agreed material rates using consistent units.', 'OPX', NULL, 'Finance', 'OPX-2027-OBJ09-FIN-G01', 'Department Goals', '37', 'Finance Manager', 'OPX-2027-OBJ09', 'Increase production lines with complete weekly waste records from 3 of 8 to all 8 by 31 March 2027, using one approved measurement method.', '{"title":"By 31 March 2027, record checked material costs for 100% of complete weekly waste records for weeks ending in March across the eight production lines. Confirm quantities with Production and apply agreed material rates using consistent units.","measure":"Complete line waste records with checked material cost / all complete line waste records","definition":"Complete line waste records with checked material cost / all complete line waste records\nDivide complete weekly line records for weeks ending in March 2027 with checked quantities and correctly applied material rates by all complete records for those weeks, then multiply by 100. Report missing or incomplete line records separately.","baseline":null,"target":100,"unit":"%","direction":"HIGHER","approach":"Establish current cost coverage and confirm reliable quantities, agreed rates, matching units and Finance time for weekly checking.","relevance":"OPX-W03 identifies incomplete waste measurement, not a measured waste-cost baseline. Confirm current cost coverage; use approved quantities and rates. This target establishes information, not an invented saving.","source":"OPX-W03 identifies incomplete waste measurement, not a measured waste-cost baseline. Confirm current cost coverage; use approved quantities and rates. This target establishes information, not an invented saving.\n\nAchievable check — department head to confirm: Establish current cost coverage and confirm reliable quantities, agreed rates, matching units and Finance time for weekly checking."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:MEX-2027-OBJ10-SAL-G01', 'department-goal', 'By 31 January 2027, record and acknowledge 100% of customer complaints within one working day of first receipt. Use one complaint register, arrange cover when the usual contact is absent and check for unanswered complaints each working day.', 'CMX', NULL, 'Sales', 'MEX-2027-OBJ10-SAL-G01', 'Department Goals', '38', 'Sales Manager', 'MEX-2027-OBJ10', 'Reduce customer complaints taking more than five working days to close from the recorded October rate of 40% to no more than 5% by 31 March 2027.', '{"title":"By 31 January 2027, record and acknowledge 100% of customer complaints within one working day of first receipt. Use one complaint register, arrange cover when the usual contact is absent and check for unanswered complaints each working day.","measure":"Complaints recorded and acknowledged within one working day / complaints received","definition":"Complaints recorded and acknowledged within one working day / complaints received\nFor complaints whose one-working-day response deadline falls in January 2027, divide those both recorded and acknowledged on time by all complaints due for a response, then multiply by 100. Start timing from the first receipt.","baseline":null,"target":100,"unit":"%","direction":"HIGHER","approach":"Confirm the starting response rate, working-day calendar and staff cover before approving the target.","relevance":"MEX-W03 gives complaint closure performance; acknowledgement performance is unknown. MEX-S02 concerns enquiries and must not be reused as a complaint baseline. Target is illustrative.","source":"MEX-W03 gives complaint closure performance; acknowledgement performance is unknown. MEX-S02 concerns enquiries and must not be reused as a complaint baseline. Target is illustrative.\n\nAchievable check — department head to confirm: Confirm the starting response rate, working-day calendar and staff cover before approving the target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:MEX-2027-OBJ10-QUA-G01', 'department-goal', 'By 28 February 2027, agree and record the action to be taken within two working days for at least 95% of complaints requiring Quality review. Count from the original complaint receipt and check progress daily with Sales and Operations.', 'CMX', NULL, 'Quality', 'MEX-2027-OBJ10-QUA-G01', 'Department Goals', '39', 'Quality Manager', 'MEX-2027-OBJ10', 'Reduce customer complaints taking more than five working days to close from the recorded October rate of 40% to no more than 5% by 31 March 2027.', '{"title":"By 28 February 2027, agree and record the action to be taken within two working days for at least 95% of complaints requiring Quality review. Count from the original complaint receipt and check progress daily with Sales and Operations.","measure":"Technical complaint responses agreed within two working days / complaints requiring technical review","definition":"Technical complaint responses agreed within two working days / complaints requiring technical review\nFor technical complaints whose two-working-day deadline falls in February 2027, divide those with an agreed response by that deadline by all technical complaints due, then multiply by 100. This measures the response, not final complaint closure.","baseline":null,"target":95,"unit":"%","direction":"HIGHER","approach":"Confirm the starting response rate, types of complaint and available review time before approving the target.","relevance":"MEX-W03 identifies slow closure but does not identify the technical-review delay or current response rate. Confirm this cause and baseline; measure from original complaint receipt. Target is illustrative.","source":"MEX-W03 identifies slow closure but does not identify the technical-review delay or current response rate. Confirm this cause and baseline; measure from original complaint receipt. Target is illustrative.\n\nAchievable check — department head to confirm: Confirm the starting response rate, types of complaint and available review time before approving the target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP),
('department-goal:MEX-2027-OBJ10-OPS-G01', 'department-goal', 'By 31 March 2027, complete at least 95% of the agreed Operations actions for customer complaints within four working days of the original complaint receipt. Plan the necessary work and materials with Quality and check open actions each day.', 'CMX', NULL, 'Operations', 'MEX-2027-OBJ10-OPS-G01', 'Department Goals', '40', 'Operations Manager', 'MEX-2027-OBJ10', 'Reduce customer complaints taking more than five working days to close from the recorded October rate of 40% to no more than 5% by 31 March 2027.', '{"title":"By 31 March 2027, complete at least 95% of the agreed Operations actions for customer complaints within four working days of the original complaint receipt. Plan the necessary work and materials with Quality and check open actions each day.","measure":"Required operational complaint remedies completed within four working days / operational remedies required","definition":"Required operational complaint remedies completed within four working days / operational remedies required\nFor required Operations actions whose four-working-day deadline falls in March 2027, divide actions completed by that deadline by all required actions due, then multiply by 100. Customer-confirmed complaint closure is checked separately.","baseline":null,"target":95,"unit":"%","direction":"HIGHER","approach":"Confirm the starting completion rate, required materials, repair time and team capacity before approving the target.","relevance":"MEX-W03 does not identify the share of complaints needing operational remedies or their present completion time. Confirm these before approval. Use the original receipt date; completing a remedy alone is not customer-confirmed closure.","source":"MEX-W03 does not identify the share of complaints needing operational remedies or their present completion time. Confirm these before approval. Use the original receipt date; completing a remedy alone is not customer-confirmed closure.\n\nAchievable check — department head to confirm: Confirm the starting completion rate, required materials, repair time and team capacity before approving the target."}'::jsonb, ARRAY['Illustrative workbook example. Replace sample evidence and figures with your organisation''s confirmed information before approval.', 'The workbook date cell is blank. Review dates in the example wording and choose a deadline for your planning period.', 'Choose a department, owner and approved company objective from your current organisation. Example codes are reference labels only.', 'No numerical baseline is supplied. Measure and confirm it before approval; a missing value is not zero.']::text[], CURRENT_TIMESTAMP)
